#!/usr/bin/env python3
from pathlib import Path
import pandas as pd,json
ROOT=Path('/home/ubuntu/CHAOS'); OUT=ROOT/'experiments/multi_domain_native_edges_v1/imf_partner_dependence_v1'; sel=pd.read_csv(OUT/'IMF_IMTS_PARTNER_SELECTION_PROFILE_V1.csv'); panel=pd.read_csv(OUT/'IMF_IMTS_PARTNER_DEPENDENCE_REPORTER_YEAR_PANEL_V1.csv'); met=pd.read_csv(OUT/'IMF_IMTS_PARTNER_DEPENDENCE_METRICS_V1.csv'); summ=json.loads((OUT/'IMF_IMTS_PARTNER_DEPENDENCE_SUMMARY_V1.json').read_text())
sel_sum=sel.groupby('reporter_id').agg(selected_partners=('partner_id','nunique'),dominant_partners=('baseline_dominant','sum'),max_share=('baseline_mean_share','max'),min_share=('baseline_mean_share','min'),mean_share=('baseline_mean_share','mean')).reset_index(); exp=panel[panel.interaction_state==True].copy(); exp_by_split={}
for name,lo,hi in [('fit',2005,2013),('validation',2014,2018),('confirmation',2019,2021)]:
 z=panel[panel.origin_year.between(lo,hi)]; exp_by_split[name]={'rows':int(len(z)),'exposures':int((z.interaction_state==True).sum()),'defined':int(z.interaction_state.notna().sum()),'reporters_exposed':int(z.loc[z.interaction_state==True,'reporter_id'].nunique()),'years_exposed':sorted(z.loc[z.interaction_state==True,'origin_year'].astype(int).unique().tolist())}
res={'selection_by_reporter':sel_sum.to_dict('records'),'dominant_count_distribution':sel_sum.dominant_partners.value_counts().sort_index().to_dict(),'selection_share_summary':{'min_baseline_mean_share':float(sel.baseline_mean_share.min()),'max_baseline_mean_share':float(sel.baseline_mean_share.max()),'median_baseline_mean_share':float(sel.baseline_mean_share.median())},'exposure_by_split':exp_by_split,'exposed_rows':int(len(exp)),'exposed_reporters':int(exp.reporter_id.nunique()),'exposure_years':sorted(exp.origin_year.astype(int).unique().tolist()),'metrics':met.to_dict('records'),'summary_status':summ['status'],'interpretation':{'coverage_failure':'Confirmation has only one positive interaction exposure, below contract minimum five; therefore not_testable.','identity_null_degeneracy':'The confirmation has one exposed reporter-year (SAU, 2020) with two shocked partners among five selected partners and four dominant slots; any reassignment of four of five slots necessarily captures at least one of the two shocks, so the identity-null statistic is constant (p=1.0, sd=0) and is non-informative about partner identity in this sample.','confirmation_direction':'All three confirmation risk differences are negative; exposed confirmation row has no positive GDP deterioration outcome.','concentration':'One reporter contributes 3 of 7 exposed rows (42.86%), exceeding the 40% cap; concentration gate fails.'}}
(OUT/'IMF_IMTS_PARTNER_DEPENDENCE_RESULT_ANALYSIS_V1.json').write_text(json.dumps(res,ensure_ascii=False,indent=2)+'\n'); print(json.dumps({'dominant_count_distribution':res['dominant_count_distribution'],'exposure_by_split':res['exposure_by_split'],'exposed_rows':res['exposed_rows'],'exposed_reporters':res['exposed_reporters'],'status':res['summary_status'],'interpretation':res['interpretation']},ensure_ascii=False,indent=2))
